const input = $input.first()?.json || {};
let desde = input.desde;
let hasta = input.hasta;
let periodoTexto = input.periodo_texto;

const MESES = [
  'enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio',
  'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'
];

if (!desde || !hasta) {
  const hoy = new Date();
  const anioActual = hoy.getFullYear();
  const mesActual = hoy.getMonth();
  const fechaMesAnterior = new Date(anioActual, mesActual - 1, 1);
  const anioPrev = fechaMesAnterior.getFullYear();
  const mesPrev = fechaMesAnterior.getMonth();
  const ultimoDiaMesPrev = new Date(anioActual, mesActual, 0).getDate();

  const pad = (n) => String(n).padStart(2, '0');
  desde = `${anioPrev}-${pad(mesPrev + 1)}-01`;
  hasta = `${anioPrev}-${pad(mesPrev + 1)}-${pad(ultimoDiaMesPrev)}`;
  periodoTexto = `${MESES[mesPrev]} de ${anioPrev}`;
}

if (!periodoTexto) {
  periodoTexto = `${desde} al ${hasta}`;
}

return [{
  json: {
    desde,
    hasta,
    periodo_texto: periodoTexto
  }
}];

const periodo = $input.first().json;
const apiKey = $env.API_KEY;
const baseUrl = 'http://tienda:8000';
const headers = {
  'X-API-Key': apiKey,
  'Content-Type': 'application/json'
};

const ventas = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/api/ventas?desde=${periodo.desde}&hasta=${periodo.hasta}`,
  headers,
  json: true
});

const abonos = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/api/abonos`,
  headers,
  json: true
});

const apartados = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/api/apartados`,
  headers,
  json: true
});

const vales = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/api/vales`,
  headers,
  json: true
});

return [{
  json: {
    periodo,
    ventas: Array.isArray(ventas) ? ventas : [],
    abonos: Array.isArray(abonos) ? abonos : [],
    apartados: Array.isArray(apartados) ? apartados : [],
    vales: Array.isArray(vales) ? vales : []
  }
}];

const datos = $input.first().json;
const { periodo, ventas, abonos, apartados, vales } = datos;
const { desde, hasta, periodo_texto } = periodo;

const totalVentas = ventas.reduce((acc, v) => acc + Number(v.importe || 0), 0);

const abonosMes = abonos.filter(a => a.fecha >= desde && a.fecha <= hasta);
const totalAbonos = abonosMes.reduce((acc, a) => acc + Number(a.importe || 0), 0);

const totalRecaudacion = totalVentas + totalAbonos;

const apartadosActivos = apartados.filter(a => a.estado === 'activo');
const totalPendiente = apartadosActivos.reduce((acc, a) => acc + Number(a.pendiente || 0), 0);

const apartadosNuevos = apartados.filter(a => a.fecha >= desde && a.fecha <= hasta);
const valesMes = vales.filter(v => v.fecha >= desde && v.fecha <= hasta);

const abonosPorApartado = {};
for (const ab of abonos) {
  if (!abonosPorApartado[ab.apartado_id]) {
    abonosPorApartado[ab.apartado_id] = [];
  }
  abonosPorApartado[ab.apartado_id].push(ab);
}

const apartadosLiquidados = apartados.filter(ap => {
  if (ap.estado !== 'liquidado') return false;
  const listaAbonos = abonosPorApartado[ap.id] || [];
  if (listaAbonos.length === 0) return false;
  listaAbonos.sort((a, b) => (a.fecha || '').localeCompare(b.fecha || '') || (a.id - b.id));
  const ultimoAbono = listaAbonos[listaAbonos.length - 1];
  return ultimoAbono.fecha >= desde && ultimoAbono.fecha <= hasta;
});

const round2 = (num) => Math.round((num + Number.EPSILON) * 100) / 100;
const fmtEuro = (num) => round2(num).toFixed(2);

const resumen = {
  periodo_texto,
  desde,
  hasta,
  total_ventas: round2(totalVentas),
  total_abonos: round2(totalAbonos),
  total_recaudacion: round2(totalRecaudacion),
  total_pendiente: round2(totalPendiente),
  nuevos_count: apartadosNuevos.length,
  liquidados_count: apartadosLiquidados.length,
  vencidos_count: valesMes.length,
  ventas_count: ventas.length,
  abonos_count: abonosMes.length
};

const html = `<h2>📊 Informe mensual · Zapatería Paso Firme</h2>
<p>Hola Marisa,</p>
<p>Aquí tienes el resumen del negocio correspondiente a <b>${periodo_texto}</b> (${desde} al ${hasta}):</p>

<h3>💰 Recaudación del mes anterior</h3>
<table border="1" cellpadding="6" style="border-collapse:collapse; width: 100%; max-width: 500px;">
  <tr><td><b>Ventas directas (${resumen.ventas_count})</b></td><td style="text-align: right;"><b>${fmtEuro(resumen.total_ventas)} €</b></td></tr>
  <tr><td><b>Abonos de apartados (${resumen.abonos_count})</b></td><td style="text-align: right;"><b>${fmtEuro(resumen.total_abonos)} €</b></td></tr>
  <tr style="background-color: #f2f2f2;"><td><b>Recaudación total mensual</b></td><td style="text-align: right;"><b>${fmtEuro(resumen.total_recaudacion)} €</b></td></tr>
</table>

<h3>📦 Estado de los apartados</h3>
<table border="1" cellpadding="6" style="border-collapse:collapse; width: 100%; max-width: 500px;">
  <tr><td><b>Total pendiente de cobro (lo que deben)</b></td><td style="text-align: right;"><b>${fmtEuro(resumen.total_pendiente)} €</b></td></tr>
  <tr><td><b>Apartados nuevos del mes</b></td><td style="text-align: right;">${resumen.nuevos_count}</td></tr>
  <tr><td><b>Apartados liquidados del mes</b></td><td style="text-align: right;">${resumen.liquidados_count}</td></tr>
  <tr><td><b>Apartados vencidos del mes</b></td><td style="text-align: right;">${resumen.vencidos_count}</td></tr>
</table>

<br>
<p>Zapatería Paso Firme · Gestión automatizada</p>`;

return [{
  json: {
    ...resumen,
    html
  }
}];
